package com.chondrimaishrat.elearning.tutoring;
import com.chondrimaishrat.elearning.user.UserAccount; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="tutoring_slots") public class TutoringSlot {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="instructor_id") private UserAccount instructor; @ManyToOne @JoinColumn(name="student_id") private UserAccount student; @Column(nullable=false) private LocalDateTime startsAt; @Column(nullable=false) private LocalDateTime endsAt; @Column(length=500) private String meetingLink; @Enumerated(EnumType.STRING) @Column(nullable=false) private SlotStatus status; protected TutoringSlot(){} public TutoringSlot(UserAccount i,LocalDateTime s,LocalDateTime e,String link){instructor=i;startsAt=s;endsAt=e;meetingLink=link;status=SlotStatus.AVAILABLE;} public Long getId(){return id;} public UserAccount getInstructor(){return instructor;} public LocalDateTime getStartsAt(){return startsAt;} public LocalDateTime getEndsAt(){return endsAt;} public String getMeetingLink(){return meetingLink;} public SlotStatus getStatus(){return status;} public void book(UserAccount s){if(status!=SlotStatus.AVAILABLE)throw new IllegalStateException("This slot is no longer available.");student=s;status=SlotStatus.BOOKED;} }
